import {MEDIA_TOPICS,mediaSearchURL,parseMediaSearch,mediaJSON,selectVideoAsset} from './media-core.mjs';
import {sha256} from './watch-core.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mediaDesk({isActive}){
  let topic='flood',type='image',items=[],selected=null,asset='',frames=[],analysis=null,status=null,busy=false,message='',observations=[],lastSearch=0;
  const $=id=>document.getElementById(id);
  function framesHTML(){return frames.map(f=>`<article><img src="${f.dataURL}" alt="Retained ${f.id}"><p>${esc(f.id)} · ${f.seconds===null?'Still image':`${f.seconds.toFixed(2)} seconds`}<br><code class="watch-hash">${f.sha256}</code></p></article>`).join('');}
  function render(){if(!isActive())return;const current=$('media-player'),same=current?.dataset.mediaId===selected?.id,resume=same&&selected?.type==='video'?current.currentTime:0,note=same?$('media-observation')?.value??'':'';$('content').innerHTML=`<section class="panel"><div class="panel-heading"><div><p class="eyebrow">PUBLIC INCIDENT MEDIA / v0.29</p><h2>Media evidence review</h2></div><span class="chip">SOURCE → SELECTED FRAMES → REVIEW</span></div><div class="case-body"><p>Search real NASA archive imagery and video about environmental events. Archive media can be old, illustrative or false-color satellite imagery; dates and descriptions remain visible. This collection is not a live incident-camera feed.</p>
    <form id="media-search" class="osint-controls"><div><label for="media-topic">Public archive topic</label><select id="media-topic"${busy?' disabled':''}>${Object.entries(MEDIA_TOPICS).map(([id,label])=>`<option value="${id}"${topic===id?' selected':''}>${label}</option>`).join('')}</select></div><div><label for="media-type">Media type</label><select id="media-type"${busy?' disabled':''}><option value="image"${type==='image'?' selected':''}>Images</option><option value="video"${type==='video'?' selected':''}>Videos</option></select></div><button class="primary"${busy?' disabled':''}>Search public NASA archive</button></form><p class="notice" role="status">${esc(message||'No media is fetched until you search. Source access policies and attribution still apply.')}</p>
    <div class="media-gallery">${items.map((m,i)=>`<article><img loading="lazy" referrerpolicy="no-referrer" src="${esc(m.preview)}" alt="${esc(m.title)}"><h3>${esc(m.title)}</h3><p>${esc(m.date)} · ${esc(m.credit)}</p><button data-media-select="${i}"${busy?' disabled':''}>Inspect ${m.type}</button></article>`).join('')}</div>
    ${selected?`<section class="media-inspector"><h3>${esc(selected.title)}</h3><p>Archive date: ${esc(selected.date)} · Credit: ${esc(selected.credit)}</p><p><a href="${esc(selected.sourceURL)}" target="_blank" rel="noopener noreferrer">Original NASA record</a></p><details><summary>Publisher description (unverified context)</summary><p>${esc(selected.description)}</p></details>${selected.type==='image'?`<img id="media-player" data-media-id="${esc(selected.id)}" crossorigin="anonymous" referrerpolicy="no-referrer" src="${esc(asset)}" alt="Selected public source image">`:asset?`<video id="media-player" data-media-id="${esc(selected.id)}" crossorigin="anonymous" src="${esc(asset)}" controls preload="metadata" playsinline></video>`:'<p>No supported small MP4 was returned. Inspect the original publisher page.</p>'}<p class="muted">Select at most three frames. Video playback time identifies the selected frame within this file; it is not a real-world event timestamp. Audio is not analyzed.</p><div class="actions"><button id="media-capture"${busy||frames.length>=3||!asset?' disabled':''}>${selected.type==='video'?'Retain current video frame':'Retain image for analysis'}</button><button id="media-clear-frames"${busy?' disabled':''}>Clear selected frames</button></div><div id="media-frames" class="media-gallery">${framesHTML()}</div>
    <form id="media-note"><label for="media-observation">Your observation (distinguish visible detail from inference)</label><textarea id="media-observation" maxlength="1500" rows="3">${esc(note)}</textarea><button${busy?' disabled':''}>Retain observation at current playback time</button></form><ul>${observations.map(o=>`<li>${esc(o.at)} · ${o.seconds===null?'Still':`${o.seconds.toFixed(2)}s`}: ${esc(o.text)}</li>`).join('')}</ul>
    <h3>Analyze the selected frames</h3><p>OpenAI receives only selected PNG frames, their frame IDs and playback times, source URL and title. No account profiles, face identification or person tracking. Results require human review.</p><button id="media-connect"${busy?' disabled':''}>Check local media AI service</button><p>${status?esc(status.enabled?`Available: ${status.model}. $1 total experiment cap; $0.05 reserved per attempt, including failures.`:'Local service present; media AI disabled.'):'Hosted static edition has no AI server. Use the local research server to enable analysis.'}</p><label class="checkline"><input id="media-approve" type="checkbox"${busy?' disabled':''}><span>These are selected public incident frames I may use. Send this selection to OpenAI for an unverified visual draft within the authorized experiment budget.</span></label><button class="primary" id="media-analyze"${busy||!frames.length||!status?.enabled?' disabled':''}>Analyze selected frames</button>
    ${analysis?`<section class="notice"><h3>AI observations — unverified draft</h3>${analysis.draft.observations.map(o=>`<p><strong>${esc(o.frameId)} · ${esc(o.confidence)} visual confidence:</strong> ${esc(o.description)}</p>`).join('')}<h4>Limitations</h4><ul>${analysis.draft.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Estimated API cost: $${analysis.estimatedCostUSD?.toFixed(6)??'unknown'} · Reserved experiment allowance: $${analysis.reservedUSD.toFixed(2)}</p></section>`:''}
    <details><summary>Media evidence record</summary><p>Copy this record to retain attribution, frame hashes, your observations and any model draft. Images remain in this tab; hashes identify the selected resized PNGs, not original publisher files. This is not a signed authenticity record.</p><textarea aria-label="Media evidence JSON" rows="12" readonly>${esc(JSON.stringify({format:'ruthless-media-evidence',version:1,source:selected,frames:frames.map(({dataURL,...f})=>f),observations,analysis},null,2))}</textarea></details></section>`:''}
    <p class="muted">The archive search is bounded to 12 results per request. No exhaustive internet/video scanning or authenticity detection is claimed. Unselected moments of a video can contain important evidence.</p></div></section>`;
    const next=$('media-player');if(next?.tagName==='VIDEO'&&resume>0)next.addEventListener('loadedmetadata',()=>{if(Number.isFinite(next.duration))next.currentTime=Math.min(resume,next.duration);},{once:true});
  }
  document.addEventListener('change',e=>{if(!isActive()||busy)return;if(e.target.id==='media-topic')topic=e.target.value;if(e.target.id==='media-type')type=e.target.value;});
  document.addEventListener('submit',async e=>{if(!isActive()||!['media-search','media-note'].includes(e.target.id))return;e.preventDefault();if(busy)return;
    if(e.target.id==='media-note'){const text=$('media-observation').value.trim();if(!text)return;observations.push({text,at:new Date().toISOString(),seconds:selected.type==='video'?$('media-player')?.currentTime??0:null});$('media-observation').value='';render();return;}
    if(Date.now()-lastSearch<30000){message='Wait 30 seconds between archive searches.';render();return;}lastSearch=Date.now();busy=true;message='Searching the public archive…';render();try{items=parseMediaSearch(await mediaJSON(mediaSearchURL(topic,type)));message=`${items.length} real archive result(s). Check dates before using them as incident evidence.`;}catch(error){message=`Search failed: ${error.message} Earlier results are retained.`;}finally{busy=false;render();}
  });
  document.addEventListener('click',async e=>{if(!isActive()||busy)return;const b=e.target.closest('button');if(!b)return;
    if(b.dataset.mediaSelect!==undefined){selected=items[Number(b.dataset.mediaSelect)];frames=[];observations=[];analysis=null;asset=selected.preview;busy=true;message='Opening selected source…';render();try{if(selected.type==='video')asset=selectVideoAsset(await mediaJSON(`https://images-api.nasa.gov/asset/${encodeURIComponent(selected.id)}`))??'';message='Source loaded. Inspect it, then retain specific frames.';}catch(error){asset='';message=error.message;}finally{busy=false;render();}return;}
    try{
      if(b.id==='media-clear-frames'){frames=[];analysis=null;render();}
      if(b.id==='media-capture'){if(frames.length>=3)return;busy=true;b.disabled=true;const player=$('media-player'),width=player.videoWidth||player.naturalWidth,height=player.videoHeight||player.naturalHeight;if(!width||!height)throw new Error('Wait for the selected image or video frame to load.');const canvas=document.createElement('canvas'),scale=Math.min(1,768/Math.max(width,height));canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));canvas.getContext('2d').drawImage(player,0,0,canvas.width,canvas.height);const dataURL=canvas.toDataURL('image/png');if(dataURL.length>1600000)throw new Error('This frame is too large for the bounded experiment.');const bytes=Uint8Array.from(atob(dataURL.split(',')[1]),c=>c.charCodeAt(0));frames.push({id:`frame-${frames.length+1}`,seconds:selected.type==='video'?player.currentTime:null,dataURL,sha256:await sha256(bytes),capturedAt:new Date().toISOString()});analysis=null;busy=false;message='Selected frame retained; no API request made.';render();}
      if(b.id==='media-connect'){const r=await fetch('/api/media/status',{credentials:'omit'});if(!r.ok)throw new Error('Local media AI service unavailable. Start scripts/serve-research.mjs --enable-media-ai locally.');status=await r.json();render();}
      if(b.id==='media-analyze'){if(!$('media-approve').checked)throw new Error('Acknowledge sending the selected public frames to OpenAI.');busy=true;message='Analyzing selected frames…';render();const r=await fetch('/api/media/analyze',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json','X-Ruthless-Request':'media-review-v1'},body:JSON.stringify({allowApi:true,publicIncident:true,sourceURL:selected.sourceURL,title:selected.title,frames:frames.map(({id,seconds,dataURL})=>({id,seconds,dataURL}))}),signal:AbortSignal.timeout(70000)});const result=await r.json();if(!r.ok)throw new Error(result.error??'Media analysis failed.');analysis=result;message='Model draft received. Review each observation against its cited frame.';busy=false;render();}
    }catch(error){busy=false;message=error.message;render();}
  });
  return {render,isBusy:()=>busy,stop:()=>{const p=$('media-player');if(p?.pause)p.pause();}};
}
